style.css:
@-moz-document domain("roblox.com") {
/* Esconde o título original de "Conexões" */
  .section-header-title {
    color: transparent !important;
    position: relative;
  }

  /* Insere "Amizades" por cima */
  .section-header-title::before {
    content: "Amizades";
    color: #ff66cc;
    font-weight: bold;
    font-size: 20px;
    position: absolute;
    left: 0;
    top: 0;
  }

  /* Estilo dos cards de amigos */
  .connection-card {
    background-color: #fff0f5 !important;
    border: 2px solid #ff66cc !important;
    border-radius: 10px !important;
    box-shadow: 0 0 10px #ff66cc !important;
  }

  /* Ícones mais arredondados */
  .avatar-card-image {
    border-radius: 50% !important;
    border: 2px solid #ff66cc !important;
  }

  /* Botão de adicionar amigo */
  .btn-primary {
    background-color: #ff66cc !important;
    border-color: #ff66cc !important;
  }

  /* Fonte divertida */
  body {
    font-family: "Comic Sans MS", cursive, sans-serif !important;
  }
}
